// Part 35: room: upper porch (interior furnisher + lamplighter). The gallery is furnished as text (one layer per y) and
// placed with layers(). Rows run along +x from x26 (the first free column past the x25 end balustrade) to x69, one row
// per z from z35 (the balustrade row, left empty) to z41 (the shutter row in front of the wall, left empty for the
// doorway lane and the window bays). Furniture is kept to the z36..z39 band; the focal table sits on the door axis x47.5.
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const X0 = 26;
const Z0 = 35;
const X1 = 69;
const Z1 = 41;

// Sparse cells ("x,z" -> character) to rows of text over the gallery's free columns.
function draw(cells) {
  const rows = [];
  for (let z = Z0; z <= Z1; z++) {
    let row = "";
    for (let x = X0; x <= X1; x++) row += cells[`${x},${z}`] ?? " ";
    rows.push(row);
  }
  return rows;
}

// Mirror pairs about x = 47.5 (x <-> 95 - x), so the room is symmetric about the door axis.
function mirror(list) {
  return list.flatMap(([x, z, ch]) => [[x, z, ch], [95 - x, z, ch]]);
}
function place(cells, list) {
  for (const [x, z, ch] of list) cells[`${x},${z}`] = ch;
  return cells;
}
----
// Part: room: bedroom 5 (east rear bedroom). Interior air x55..60, z54..60, floor y11, air y11..16.
// Entered from the west wall (door x54 z57, lane kept clear at x55 z56..57); keep-clear cells for the other
// candidate doorways (north x56 z53, east x61 z56..57) stay free too. Bed on the west wall (head x55 z58), barrel
// nightstand with a lantern, a two-chest dresser on the north wall, a red rug in the middle, a barrel side table in
// the SE corner with a flower pot, and a hanging lantern from the plate.
//
// Built nothing yet: the shell (parts/shell.mjs) carves every interior cell of the upper floor to air, and runParts
// locks air like any block, so each write here was refused (21 of 21). The layout is kept below for when the shell
// leaves these air cells unclaimed (or a part is given { carve: true } to lay them). Restore by uncommenting:
//
//   layers(g, [55, 11, 54], { C: ["chest", { facing: "south" }], R: "red_carpet", K: "barrel" }, [[
//     "..CC..", // z54: dresser chests on the north wall (x57, x58); x56 kept clear for the north doorway
//     "..RRR.", // z55: red rug x57..59, z55..57
//     "..RRR.", // z56
//     "..RRR.", // z57: west lane (x55) and east doorway cells (x60) stay free
//     "......", // z58: bed goes here
//     "K.....", // z59: nightstand barrel at x55 (south of the bed head)
//     ".....K", // z60: side table barrel at x60 (SE corner)
//   ]]);
//   layers(g, [55, 12, 54], { N: ["lantern", { hanging: "false" }], P: "flower_pot" }, [[
